head.b:skin:
body {
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}
.custom-scrollbar::-webkit-scrollbar {
  width: 6px;
}
.custom-scrollbar::-webkit-scrollbar-track {
  background: transparent;
}
.custom-scrollbar::-webkit-scrollbar-thumb {
  background: rgba(156, 163, 175, 0.5);
  border-radius: 9999px;
}

body.script:
//
import { initializeApp } from 'https://www.gstatic.com/firebasejs/10.9.0/firebase-app.js';
import { 
  getAuth, 
  GoogleAuthProvider, 
  signInWithPopup, 
  signOut, 
  onAuthStateChanged 
} from 'https://www.gstatic.com/firebasejs/10.9.0/firebase-auth.js';
import { 
  getFirestore, 
  collection, 
  addDoc, 
  getDocs, 
  query, 
  where, 
  orderBy, 
  limit, 
  onSnapshot, 
  doc, 
  setDoc, 
  updateDoc, 
  increment, 
  serverTimestamp 
} from 'https://www.gstatic.com/firebasejs/10.9.0/firebase-firestore.js';

// CẤU HÌNH FIREBASE PROJECT: Blogger
const firebaseConfig = {
  apiKey: "AIzaSyDummyKeyForTayNinhInfoBlogger2026",
  authDomain: "blogger-tayninhinfo.firebaseapp.com",
  projectId: "Blogger",
  storageBucket: "blogger-tayninhinfo.appspot.com",
  messagingSenderId: "109876543210",
  appId: "1:109876543210:web:abcdef1234567890"
};

// Google Apps Script Web App URL
const GAS_WEB_APP_URL = "https://script.google.com/macros/s/AKfycbzDummyBloggerWebDeploymentIdForTayNinhInfo/exec";

// Initialize Firebase
const app = initializeApp(firebaseConfig);
const auth = getAuth(app);
const db = getFirestore(app);

const { createApp, ref, computed, onMounted } = Vue;

createApp({
  setup() {
    const isDark = ref(false);
    const currentUser = ref(null);
    const userMenuOpen = ref(false);
    const activeTab = ref('all');
    const selectedCategory = ref('all');
    const searchKeyword = ref('');
    const loading = ref(true);

    const posts = ref([]);
    const bookmarks = ref(JSON.parse(localStorage.getItem('tayninh_bookmarks') || '[]'));
    const likedPostIds = ref(new Set(JSON.parse(localStorage.getItem('tayninh_likes') || '[]')));

    const activeCommentPostId = ref(null);
    const postComments = ref({});
    const newCommentText = ref('');

    const showApplyModal = ref(false);
    const selectedJobToApply = ref(null);
    const submittingApply = ref(false);
    const applyForm = ref({
      fullName: '',
      phone: '',
      email: '',
      note: '',
      fileBase64: null,
      fileName: ''
    });

    const showCreateModal = ref(false);
    const submittingPost = ref(false);
    const postForm = ref({
      title: '',
      category: 'tintuc',
      salary: '',
      location: '',
      content: '',
      imageBase64: null,
      imageName: ''
    });

    const userStats = ref({
      postsCount: 12,
      reputation: 98
    });

    const categories = ref([
      { id: 'all', name: 'Tất cả danh mục', icon: 'fa-solid fa-list', color: 'bg-slate-700' },
      { id: 'tintuc', name: 'Tin tức Tây Ninh', icon: 'fa-solid fa-newspaper', color: 'bg-emerald-600', badge: 'Mới' },
      { id: 'tuyendung', name: 'Tuyển dụng & Việc làm', icon: 'fa-solid fa-briefcase', color: 'bg-blue-600', badge: 'Hot' },
      { id: 'raovat', name: 'Rao vặt - Mua bán', icon: 'fa-solid fa-tag', color: 'bg-amber-600' },
      { id: 'diadiem', name: 'Địa điểm & Review', icon: 'fa-solid fa-map-location-dot', color: 'bg-rose-600' }
    ]);

    const urgentJobs = ref([
      { id: 'j1', title: 'Kỹ sư Vận hành Máy CNC', company: 'Tập đoàn KCN Phước Đông', salary: '12 - 18 Triệu', location: 'Gò Dầu, Tây Ninh' },
      { id: 'j2', title: 'Nhân viên Xuất Nhập Khẩu', company: 'Logistics Mộc Bài Tây Ninh', salary: '10 - 15 Triệu', location: 'Bến Cầu, Tây Ninh' },
      { id: 'j3', title: 'Quản trị viên Nhà hàng SunWorld', company: 'KDL Quốc gia Núi Bà Đen', salary: '9 - 14 Triệu', location: 'TP. Tây Ninh' }
    ]);

    const leaderboard = ref([
      { id: 'u1', name: 'Trần Văn Hưng', points: 1450, avatar: 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=80&h=80&q=80' },
      { id: 'u2', name: 'Lê Thị Mai Thảo', points: 1220, avatar: 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=80&h=80&q=80' },
      { id: 'u3', name: 'Nguyễn Thành Đạt', points: 980, avatar: 'https://images.unsplash.com/photo-1570295999919-56ceb5ecca61?auto=format&fit=crop&w=80&h=80&q=80' }
    ]);

    // Toggle Dark Theme
    const toggleDarkMode = () => {
      isDark.value = !isDark.value;
      if (isDark.value) {
        document.documentElement.classList.add('dark');
        localStorage.setItem('theme', 'dark');
      } else {
        document.documentElement.classList.remove('dark');
        localStorage.setItem('theme', 'light');
      }
    };

    // Firebase Auth Google
    const loginGoogle = async () => {
      try {
        const provider = new GoogleAuthProvider();
        const res = await signInWithPopup(auth, provider);
        const user = res.user;
        await setDoc(doc(db, 'users', user.uid), {
          uid: user.uid,
          displayName: user.displayName,
          email: user.email,
          photoURL: user.photoURL,
          lastLogin: serverTimestamp()
        }, { merge: true });
      } catch (err) {
        alert('Lỗi đăng nhập: ' + err.message);
      }
    };

    const logout = async () => {
      await signOut(auth);
      userMenuOpen.value = false;
    };

    // Listen Auth State
    onAuthStateChanged(auth, (user) => {
      currentUser.value = user;
      if (user) {
        applyForm.value.fullName = user.displayName || '';
        applyForm.value.email = user.email || '';
      }
    });

    // Filter Posts
    const filteredPosts = computed(() => {
      let list = [...posts.value];
      if (selectedCategory.value !== 'all') {
        list = list.filter(p => p.category === selectedCategory.value);
      }
      if (activeTab.value === 'tuyendung') {
        list = list.filter(p => p.category === 'tuyendung' || p.isJob);
      } else if (activeTab.value === 'thaoluan') {
        list = list.filter(p => p.category === 'tintuc' || p.category === 'diadiem');
      } else if (activeTab.value === 'bookmark') {
        list = list.filter(p => bookmarks.value.includes(p.id));
      }
      if (searchKeyword.value.trim()) {
        const kw = searchKeyword.value.toLowerCase();
        list = list.filter(p => (p.title && p.title.toLowerCase().includes(kw)) || (p.content && p.content.toLowerCase().includes(kw)));
      }
      return list;
    });

    const selectCategory = (catId) => {
      selectedCategory.value = catId;
      activeTab.value = 'all';
    };

    // Fetch Blogger Feed & Merge with Firestore
    const loadInitialData = async () => {
      loading.value = true;
      const merged = [];

      try {
        // 1. Fetch Blogger Native Feed JSON
        const feedRes = await fetch('/feeds/posts/default?alt=json&max-results=10');
        if (feedRes.ok) {
          const feedData = await feedRes.json();
          if (feedData.feed && feedData.feed.entry) {
            feedData.feed.entry.forEach(entry => {
              const title = entry.title.$t;
              const content = entry.content ? entry.content.$t.replace(/<[^>]*>?/gm, '').substring(0, 220) + '...' : '';
              const url = entry.link.find(l => l.rel === 'alternate')?.href || '#';
              const published = entry.published.$t;
              const id = 'blogger_' + entry.id.$t.split('post-')[1];
              const img = entry.media$thumbnail ? entry.media$thumbnail.url.replace('/s72-c/', '/s1600/') : null;

              merged.push({
                id,
                title,
                content,
                url,
                authorName: entry.author[0]?.name.$t || 'Ban Biên Tập Tây Ninh',
                authorPhoto: 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=120&h=120&q=80',
                createdAt: new Date(published).getTime(),
                category: 'tintuc',
                imageUrl: img,
                isVerified: true,
                likes: 15,
                commentCount: 4
              });
            });
          }
        }
      } catch (e) {
        console.warn('Blogger feed fetch skipped or offline, using live data.');
      }

      // 2. Fetch Realtime Firestore Community Posts
      try {
        const q = query(collection(db, 'posts'), orderBy('createdAt', 'desc'), limit(20));
        onSnapshot(q, (snapshot) => {
          const livePosts = [];
          snapshot.forEach(docSnap => {
            livePosts.push({ id: docSnap.id, ...docSnap.data() });
          });

          // Merge Firestore with Blogger feed
          posts.value = [...livePosts, ...merged].sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));
          loading.value = false;
        });
      } catch (err) {
        console.error('Firestore sync error:', err);
        posts.value = merged;
        loading.value = false;
      }
    };

    // Likes & Bookmarks
    const isPostLiked = (post) => likedPostIds.value.has(post.id);
    const toggleLike = async (post) => {
      if (!currentUser.value) {
        alert('Vui lòng đăng nhập để thả tim bài viết!');
        return;
      }
      if (likedPostIds.value.has(post.id)) {
        likedPostIds.value.delete(post.id);
        post.likes = Math.max(0, (post.likes || 1) - 1);
      } else {
        likedPostIds.value.add(post.id);
        post.likes = (post.likes || 0) + 1;
        // Update Firestore meta
        try {
          const refDoc = doc(db, 'posts_meta', post.id);
          await setDoc(refDoc, { likes: increment(1) }, { merge: true });
        } catch (e) {}
      }
      localStorage.setItem('tayninh_likes', JSON.stringify([...likedPostIds.value]));
    };

    const isBookmarked = (id) => bookmarks.value.includes(id);
    const toggleBookmark = (post) => {
      const idx = bookmarks.value.indexOf(post.id);
      if (idx >= 0) {
        bookmarks.value.splice(idx, 1);
      } else {
        bookmarks.value.push(post.id);
      }
      localStorage.setItem('tayninh_bookmarks', JSON.stringify(bookmarks.value));
    };

    const sharePost = (post) => {
      if (navigator.share) {
        navigator.share({
          title: post.title || 'Bài viết từ TayNinhInfo',
          text: post.content,
          url: post.url || window.location.href
        }).catch(() => {});
      } else {
        navigator.clipboard.writeText(post.url || window.location.href);
        alert('Đã sao chép liên kết vào clipboard!');
      }
    };

    // Comments System
    const toggleCommentSection = (postId) => {
      if (activeCommentPostId.value === postId) {
        activeCommentPostId.value = null;
      } else {
        activeCommentPostId.value = postId;
        loadComments(postId);
      }
    };

    const loadComments = (postId) => {
      const q = query(collection(db, 'comments'), where('postId', '==', postId), orderBy('createdAt', 'asc'));
      onSnapshot(q, (snapshot) => {
        const list = [];
        snapshot.forEach(docSnap => list.push({ id: docSnap.id, ...docSnap.data() }));
        postComments.value[postId] = list;
      });
    };

    const submitComment = async (postId) => {
      if (!currentUser.value) {
        alert('Vui lòng đăng nhập để bình luận!');
        return;
      }
      if (!newCommentText.value.trim()) return;

      try {
        await addDoc(collection(db, 'comments'), {
          postId: postId,
          authorId: currentUser.value.uid,
          authorName: currentUser.value.displayName,
          authorPhoto: currentUser.value.photoURL,
          text: newCommentText.value.trim(),
          createdAt: Date.now()
        });
        newCommentText.value = '';
      } catch (err) {
        alert('Lỗi đăng bình luận: ' + err.message);
      }
    };

    // 1-Click Apply Flow
    const openApplyModal = (job) => {
      selectedJobToApply.value = job;
      showApplyModal.value = true;
    };

    const handleFileUpload = (e) => {
      const file = e.target.files[0];
      if (!file) return;
      applyForm.value.fileName = file.name;
      const reader = new FileReader();
      reader.onload = (evt) => {
        applyForm.value.fileBase64 = evt.target.result;
      };
      reader.readAsDataURL(file);
    };

    const submitApplication = async () => {
      submittingApply.value = true;
      try {
        // 1. Lưu vào Firestore
        const docRef = await addDoc(collection(db, 'job_applications'), {
          jobId: selectedJobToApply.value.id,
          jobTitle: selectedJobToApply.value.title,
          userId: currentUser.value ? currentUser.value.uid : 'anonymous',
          fullName: applyForm.value.fullName,
          phone: applyForm.value.phone,
          email: applyForm.value.email,
          note: applyForm.value.note,
          hasFile: !!applyForm.value.fileBase64,
          createdAt: Date.now()
        });

        // 2. Gửi file đính kèm & kích hoạt email qua Google Apps Script
        if (GAS_WEB_APP_URL && !GAS_WEB_APP_URL.includes('Dummy')) {
          await fetch(GAS_WEB_APP_URL, {
            method: 'POST',
            mode: 'no-cors',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              action: 'apply_job',
              jobTitle: selectedJobToApply.value.title,
              fullName: applyForm.value.fullName,
              phone: applyForm.value.phone,
              email: applyForm.value.email,
              note: applyForm.value.note,
              fileBase64: applyForm.value.fileBase64,
              fileName: applyForm.value.fileName
            })
          });
        }

        alert('Chúc mừng! Đã gửi hồ sơ ứng tuyển thành công. Nhà tuyển dụng sẽ sớm liên hệ qua SĐT/Email.');
        showApplyModal.value = false;
        applyForm.value.note = '';
      } catch (err) {
        alert('Lỗi khi nộp hồ sơ: ' + err.message);
      } finally {
        submittingApply.value = false;
      }
    };

    // Quick Post Flow
    const openCreatePostModal = (cat) => {
      if (!currentUser.value) {
        alert('Vui lòng đăng nhập bằng Google trước khi đăng tin!');
        return;
      }
      postForm.value.category = cat || 'tintuc';
      showCreateModal.value = true;
    };

    const handlePostImageUpload = (e) => {
      const file = e.target.files[0];
      if (!file) return;
      postForm.value.imageName = file.name;
      const reader = new FileReader();
      reader.onload = (evt) => {
        postForm.value.imageBase64 = evt.target.result;
      };
      reader.readAsDataURL(file);
    };

    const submitPost = async () => {
      submittingPost.value = true;
      try {
        let uploadedImageUrl = null;

        // Đẩy ảnh lên Google Drive qua GAS Web App
        if (postForm.value.imageBase64 && GAS_WEB_APP_URL && !GAS_WEB_APP_URL.includes('Dummy')) {
          try {
            const res = await fetch(GAS_WEB_APP_URL, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                action: 'upload_image',
                fileBase64: postForm.value.imageBase64,
                fileName: postForm.value.imageName
              })
            });
            const data = await res.json();
            if (data && data.fileUrl) {
              uploadedImageUrl = data.fileUrl;
            }
          } catch (e) {
            console.warn('Lưu ảnh Google Drive thất bại, dùng Base64 trực tiếp');
            uploadedImageUrl = postForm.value.imageBase64;
          }
        }

        // Ghi vào Firestore
        await addDoc(collection(db, 'posts'), {
          title: postForm.value.title,
          content: postForm.value.content,
          category: postForm.value.category,
          salary: postForm.value.salary || null,
          location: postForm.value.location || null,
          imageUrl: uploadedImageUrl,
          authorId: currentUser.value.uid,
          authorName: currentUser.value.displayName,
          authorPhoto: currentUser.value.photoURL,
          isVerified: true,
          likes: 1,
          commentCount: 0,
          createdAt: Date.now()
        });

        // Đồng bộ sang bài viết Blogger qua Google Apps Script (Blogger API v3)
        if (GAS_WEB_APP_URL && !GAS_WEB_APP_URL.includes('Dummy')) {
          fetch(GAS_WEB_APP_URL, {
            method: 'POST',
            mode: 'no-cors',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              action: 'create_blogger_post',
              title: postForm.value.title,
              content: `<p>${postForm.value.content}</p>${uploadedImageUrl ? `<img src="${uploadedImageUrl}"/>` : ''}`,
              labels: ['TayNinhInfo', postForm.value.category],
              isDraft: false
            })
          });
        }

        alert('Đăng bài thành công!');
        showCreateModal.value = false;
        postForm.value = { title: '', category: 'tintuc', salary: '', location: '', content: '', imageBase64: null, imageName: '' };
      } catch (err) {
        alert('Lỗi khi đăng bài: ' + err.message);
      } finally {
        submittingPost.value = false;
      }
    };

    const formatRelativeTime = (timestamp) => {
      if (!timestamp) return 'Vừa xong';
      const diff = Math.floor((Date.now() - Number(timestamp)) / 1000);
      if (diff < 60) return 'Vừa xong';
      if (diff < 3600) return Math.floor(diff / 60) + ' phút trước';
      if (diff < 86400) return Math.floor(diff / 3600) + ' giờ trước';
      return Math.floor(diff / 86400) + ' ngày trước';
    };

    onMounted(() => {
      const savedTheme = localStorage.getItem('theme');
      if (savedTheme === 'dark' || (!savedTheme && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
        isDark.value = true;
        document.documentElement.classList.add('dark');
      }
      loadInitialData();
    });

    return {
      isDark,
      toggleDarkMode,
      currentUser,
      userMenuOpen,
      loginGoogle,
      logout,
      userStats,
      categories,
      selectedCategory,
      selectCategory,
      activeTab,
      searchKeyword,
      loading,
      filteredPosts,
      bookmarks,
      isPostLiked,
      toggleLike,
      isBookmarked,
      toggleBookmark,
      sharePost,
      activeCommentPostId,
      toggleCommentSection,
      postComments,
      newCommentText,
      submitComment,
      urgentJobs,
      leaderboard,
      showApplyModal,
      selectedJobToApply,
      submittingApply,
      applyForm,
      openApplyModal,
      handleFileUpload,
      submitApplication,
      showCreateModal,
      submittingPost,
      postForm,
      openCreatePostModal,
      handlePostImageUpload,
      submitPost,
      formatRelativeTime
    };
  }
}).mount('#app');
//
